-- L02-K2-team-accounts.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   creates the 31 Team accounts of OtakuQuiz on the anime site: a profile through create_profile_for_site (joined_via seed),
--         the display name and avatar, the editorial_accounts row (the Team badge, off every board), the anime membership with its bio and
--         header, and sites.system_user_id (the daily quiz author) and sites.fallback_group_slug (anime-mix) of anime.
-- Needs:  L01, 003, 009; the auth users must exist first (node apps/quiz/e2e/o1/L1/team-auth.mjs, run by the owner); the file stops with a
--         clear message when they do not.
-- Rows:   31 profiles, 31 editorial_accounts, 31 anime memberships, 1 sites row updated.
-- Verify: select count(*) from public.editorial_accounts where site_id = 'anime' and active;   expect 31
-- Undo:   L02-K2-team-accounts.rollback.sql (refused while a Team account has a quiz).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if not exists (select 1 from public.sites where id = 'anime') or to_regclass('public.editorial_accounts') is null or to_regclass('public.world_memberships') is null then
    raise exception 'L02: apply L01, 003 and 012 first';
  end if;
end $o1l$;

do $o1l$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'sites' and column_name = 'system_user_id') then
    raise exception 'L02: sites.system_user_id is missing (apply 009 first)';
  end if;
end $o1l$;

do $o1l$ begin
  if (select count(*) from auth.users u join (values
  ('oq_creator_01', 'oq_creator_01@team.bunnyverse.org'),
  ('oq_creator_02', 'oq_creator_02@team.bunnyverse.org'),
  ('oq_creator_03', 'oq_creator_03@team.bunnyverse.org'),
  ('oq_creator_04', 'oq_creator_04@team.bunnyverse.org'),
