  ('oq_creator_08', 'oq_creator_08@team.bunnyverse.org'),
  ('oq_creator_09', 'oq_creator_09@team.bunnyverse.org'),
  ('oq_creator_10', 'oq_creator_10@team.bunnyverse.org'),
  ('oq_creator_11', 'oq_creator_11@team.bunnyverse.org'),
  ('oq_creator_12', 'oq_creator_12@team.bunnyverse.org'),
  ('oq_creator_13', 'oq_creator_13@team.bunnyverse.org'),
  ('oq_creator_14', 'oq_creator_14@team.bunnyverse.org'),
  ('oq_creator_15', 'oq_creator_15@team.bunnyverse.org'),
  ('oq_creator_16', 'oq_creator_16@team.bunnyverse.org'),
  ('oq_creator_17', 'oq_creator_17@team.bunnyverse.org'),
  ('oq_creator_18', 'oq_creator_18@team.bunnyverse.org'),
  ('oq_creator_19', 'oq_creator_19@team.bunnyverse.org'),
  ('oq_creator_20', 'oq_creator_20@team.bunnyverse.org'),
  ('oq_creator_21', 'oq_creator_21@team.bunnyverse.org'),
  ('oq_creator_22', 'oq_creator_22@team.bunnyverse.org'),
  ('oq_creator_23', 'oq_creator_23@team.bunnyverse.org'),
  ('oq_creator_24', 'oq_creator_24@team.bunnyverse.org'),
  ('oq_creator_25', 'oq_creator_25@team.bunnyverse.org'),
  ('oq_creator_26', 'oq_creator_26@team.bunnyverse.org'),
  ('oq_creator_27', 'oq_creator_27@team.bunnyverse.org'),
  ('oq_creator_28', 'oq_creator_28@team.bunnyverse.org'),
  ('oq_creator_29', 'oq_creator_29@team.bunnyverse.org'),
  ('oq_creator_30', 'oq_creator_30@team.bunnyverse.org'),
  ('otakuquiz_team', 'otakuquiz_team@team.bunnyverse.org')
) as t(username, email) on u.email = t.email) <> 31 then
    raise exception 'L02: the Team auth users are missing (run team-auth.mjs first)';
  end if;
end $o1l$;

