) as t(username, email)
  join auth.users u on u.email = t.email
  where not exists (select 1 from public.profiles p where p.id = u.id)
) s;

update public.profiles p set display_name = v.display_name, avatar_url = v.avatar_url from (values ('oq_creator_01', 'Mina Okabe', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_01-avatar.svg'), ('oq_creator_02', 'Kenji Aoyama', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_02-avatar.svg'), ('oq_creator_03', 'Hana Verhoeven', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_03-avatar.svg'), ('oq_creator_04', 'Ravi Santoro', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_04-avatar.svg'), ('oq_creator_05', 'Sora Whitfield', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_05-avatar.svg'), ('oq_creator_06', 'Emi Takeda', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_06-avatar.svg'), ('oq_creator_07', 'Lars Brandt', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_07-avatar.svg'), ('oq_creator_08', 'Tomas Ibarra', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_08-avatar.svg'), ('oq_creator_09', 'Priya Nandakumar', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_09-avatar.svg'), ('oq_creator_10', 'Daniel Cho', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_10-avatar.svg'), ('oq_creator_11', 'Rin Matsuda', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_11-avatar.svg'), ('oq_creator_12', 'Jules Marchetti', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_12-avatar.svg'), ('oq_creator_13', 'Yuna Park', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_13-avatar.svg'), ('oq_creator_14', 'Elena Voss', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_14-avatar.svg'), ('oq_creator_15', 'Akira Winters', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_15-avatar.svg'), ('oq_creator_16', 'Hugo Ferreira', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_16-avatar.svg'), ('oq_creator_17', 'Noa Lindqvist', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_17-avatar.svg'), ('oq_creator_18', 'Bastien Roy', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_18-avatar.svg'), ('oq_creator_19', 'Chiara Moretti', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_19-avatar.svg'), ('oq_creator_20', 'Matteo Ricci', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_20-avatar.svg'), ('oq_creator_21', 'Ingrid Solheim', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_21-avatar.svg'), ('oq_creator_22', 'Dario Esposito', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_22-avatar.svg'), ('oq_creator_23', 'Camille Duval', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_23-avatar.svg'), ('oq_creator_24', 'Tobias Klein', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_24-avatar.svg'), ('oq_creator_25', 'Mei Lin Zhao', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_25-avatar.svg'), ('oq_creator_26', 'Felix Andersson', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_26-avatar.svg'), ('oq_creator_27', 'Seo-yeon Han', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_27-avatar.svg'), ('oq_creator_28', 'Oscar Beaumont', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_28-avatar.svg'), ('oq_creator_29', 'Lucia Moreau', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_29-avatar.svg'), ('oq_creator_30', 'Henrik Dahl', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_30-avatar.svg'), ('otakuquiz_team', 'OtakuQuiz Team', 'https://bunnyverse.org/anime/brand/anime/creators/otakuquiz_team-avatar.svg')) as v(username, display_name, avatar_url) where p.username = v.username and (p.display_name, p.avatar_url) is distinct from (v.display_name, v.avatar_url);

insert into public.editorial_accounts (user_id, display_name, beat, active, site_id) select p.id, v.display_name, v.beat, true, 'anime' from (values ('oq_creator_01', 'Mina Okabe', 'Death Note: rules, cat and mouse, and the detectives'), ('oq_creator_02', 'Kenji Aoyama', 'One Piece: crews, bounties, islands and the long road'), ('oq_creator_03', 'Hana Verhoeven', 'Spy x Family: the Forgers, missions and everyday comedy'), ('oq_creator_04', 'Ravi Santoro', 'Naruto and Shippuden: arcs, openings and the village'), ('oq_creator_05', 'Sora Whitfield', 'Jujutsu Kaisen: sorcerers, arcs and the studio behind the fights'), ('oq_creator_06', 'Emi Takeda', 'Demon Slayer: arcs, breathing styles and the animation'), ('oq_creator_07', 'Lars Brandt', 'Attack on Titan: seasons, arcs and how the story was made'), ('oq_creator_08', 'Tomas Ibarra', 'Dragon Ball: sagas, forms, transformations and the TV runs'), ('oq_creator_09', 'Priya Nandakumar', 'My Hero Academia: quirks, classes and the hero society'), ('oq_creator_10', 'Daniel Cho', 'Solo Leveling: hunters, gates, the webnovel and the anime'), ('oq_creator_11', 'Rin Matsuda', 'Bleach: Soul Reapers, Hollows, arcs and the long hiatus'), ('oq_creator_12', 'Jules Marchetti', 'Chainsaw Man: devils, public safety and the anime'), ('oq_creator_13', 'Yuna Park', 'Dandadan: yokai, aliens, Science SARU and the manga'), ('oq_creator_14', 'Elena Voss', 'Frieren: Beyond Journey''s End: the journey, the music and the craft'), ('oq_creator_15', 'Akira Winters', 'Fullmetal Alchemist: both anime, the manga and alchemy'), ('oq_creator_16', 'Hugo Ferreira', 'Haikyu!!: volleyball, teams, seasons and the music'), ('oq_creator_17', 'Noa Lindqvist', 'Hunter x Hunter: exams, arcs, Nen and the two anime'), ('oq_creator_18', 'Bastien Roy', 'JoJo''s Bizarre Adventure: parts, Stands and the poses'), ('oq_creator_19', 'Chiara Moretti', 'Oshi no Ko: idols, entertainment and the anime'), ('oq_creator_20', 'Matteo Ricci', 'Tower of God: the Tower, tests and the webtoon'), ('oq_creator_21', 'Ingrid Solheim', 'Court mysteries and the Apothecary Diaries; mixed formats'), ('oq_creator_22', 'Dario Esposito', 'Sports rivalries: Blue Lock and ranked mixed sets'), ('oq_creator_23', 'Camille Duval', 'Classic anime and soundtracks: Cowboy Bebop first'), ('oq_creator_24', 'Tobias Klein', 'Mecha and 90s landmarks: Evangelion and mixed sets'), ('oq_creator_25', 'Mei Lin Zhao', 'New releases and simulpub manga: Kagurabachi and mixed sets'), ('oq_creator_26', 'Felix Andersson', 'Action newcomers: Kaiju No. 8 and mixed formats'), ('oq_creator_27', 'Seo-yeon Han', 'Webnovel and webtoon adaptations, Omniscient Reader''s Viewpoint'), ('oq_creator_28', 'Oscar Beaumont', 'Parody and comedy: One-Punch Man and mixed sets'), ('oq_creator_29', 'Lucia Moreau', 'Magical girl classics: Sailor Moon and mixed formats'), ('oq_creator_30', 'Henrik Dahl', 'Historical epics: Vinland Saga and mixed sets'), ('otakuquiz_team', 'OtakuQuiz Team', 'Daily quiz and Anime Mix: mixed formats across series')) as v(username, display_name, beat) join public.profiles p on p.username = v.username on conflict (user_id) do update set display_name = excluded.display_name, beat = excluded.beat, active = true, site_id = excluded.site_id;

insert into public.world_memberships (user_id, site_id, joined_via, activated_at, bio, header_url) select p.id, 'anime', 'seed', now(), v.bio, v.header_url from (values ('oq_creator_01', 'Writes the Death Note desk. Likes a clean rule, a tight timeline and a question that rewards careful viewers over fast clickers.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_01-header.svg'), ('oq_creator_02', 'Covers the One Piece desk. Keeps a running map of crews and islands and prefers facts a fan can check in a minute.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_02-header.svg'), ('oq_creator_03', 'Spy x Family desk. Writes friendly quizzes about the Forger household and the missions that hold the cover story together.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_03-header.svg'), ('oq_creator_04', 'Naruto desk. Counts episodes, ranks openings and knows which arcs are filler. Happy to settle a canon argument with a source.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_04-header.svg'), ('oq_creator_05', 'Jujutsu Kaisen desk. Tracks arcs, studio credits and sorcerer ranks, and tags every spoiler honestly before it reaches a starter.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_05-header.svg'), ('oq_creator_06', 'Demon Slayer desk. Likes the arc order, the breathing styles and the production notes that explain why the show looks the way it does.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_06-header.svg'), ('oq_creator_07', 'Attack on Titan desk. Handles a spoiler-heavy series with care, so newcomers get safe quizzes and veterans get honest hard ones.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_07-header.svg'), ('oq_creator_08', 'Dragon Ball desk. Keeps the sagas, series and films straight, and the difference between Z, GT and Super.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_08-header.svg'), ('oq_creator_09', 'My Hero Academia desk. Writes about U.A., hero names and quirks, and keeps each arc labelled for fans at every pace.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_09-header.svg'), ('oq_creator_10', 'Solo Leveling desk. Follows the webnovel, the manhwa and the anime, and keeps the three versions from blurring together.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_10-header.svg'), ('oq_creator_11', 'Bleach desk. Covers the original run and the Thousand-Year Blood War return, with labels on every arc.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_11-header.svg'), ('oq_creator_12', 'Chainsaw Man desk. Writes about devils, Public Safety and the Studio MAPPA anime, keeping part one spoilers marked.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_12-header.svg'), ('oq_creator_13', 'Dandadan desk. Follows the manga and the Science SARU anime, and likes the details that make the mix of yokai and aliens work.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_13-header.svg'), ('oq_creator_14', 'Frieren desk. Writes slow, careful quizzes about the party, the journey and the craft of the anime.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_14-header.svg'), ('oq_creator_15', 'Fullmetal Alchemist desk. Keeps the 2003 anime and Brotherhood apart, and checks every claim against the right version.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_15-header.svg'), ('oq_creator_16', 'Haikyu desk. Writes about the teams, the seasons and the sport itself, with a real volleyball rulebook nearby.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_16-header.svg'), ('oq_creator_17', 'Hunter x Hunter desk. Keeps the 1999, 2011 and manga runs straight and labels every arc.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_17-header.svg'), ('oq_creator_18', 'JoJo desk. Moves part by part, with Stand names exact and the references to music kept in the notes, not in the answers.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_18-header.svg'), ('oq_creator_19', 'Oshi no Ko desk. Handles the idol industry setting and the anime seasons, with spoiler tags kept strict from the first question.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_19-header.svg'), ('oq_creator_20', 'Tower of God desk. Follows the webtoon and the anime, and keeps the tests, floors and factions in order.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_20-header.svg'), ('oq_creator_21', 'Writes court drama and mystery quizzes, from the Apothecary Diaries to short true or false sets that reward patient viewers.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_21-header.svg'), ('oq_creator_22', 'Covers sports anime rivalries, starting with Blue Lock, and builds mixed sets around teams, rankings and matches.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_22-header.svg'), ('oq_creator_23', 'Writes about classics and their music, starting with Cowboy Bebop. Likes a good question about who composed what.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_23-header.svg'), ('oq_creator_24', 'Covers mecha and 90s landmark anime, with Evangelion as the anchor and short mixed sets around it.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_24-header.svg'), ('oq_creator_25', 'Covers new and still-running manga, starting with Kagurabachi, and keeps every quiz inside what has been printed.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_25-header.svg'), ('oq_creator_26', 'Writes about recent action anime, starting with Kaiju No. 8, in tidy mixed formats for fans catching up.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_26-header.svg'), ('oq_creator_27', 'Covers webnovel, webtoon and manhwa adaptations, starting with Omniscient Reader''s Viewpoint, and says which version each fact belongs to.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_27-header.svg'), ('oq_creator_28', 'Writes comedy and parody quizzes, starting with One-Punch Man, with true or false sets that stay funny and accurate.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_28-header.svg'), ('oq_creator_29', 'Covers magical girl classics, starting with Sailor Moon, and mixes character, music and production questions.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_29-header.svg'), ('oq_creator_30', 'Covers historical epics, starting with Vinland Saga, and checks anything about real history against a source.', 'https://bunnyverse.org/anime/brand/anime/creators/oq_creator_30-header.svg'), ('otakuquiz_team', 'The OtakuQuiz editorial desk. Runs the daily quiz and Anime Mix, and signs the sets that cross series.', 'https://bunnyverse.org/anime/brand/anime/creators/otakuquiz_team-header.svg')) as v(username, bio, header_url) join public.profiles p on p.username = v.username on conflict (user_id, site_id) do update set bio = excluded.bio, header_url = excluded.header_url, activated_at = coalesce(public.world_memberships.activated_at, excluded.activated_at);

update public.sites set system_user_id = (select id from public.profiles where username = 'otakuquiz_team') where id = 'anime' and system_user_id is null;

update public.sites set fallback_group_slug = 'anime-mix' where id = 'anime' and fallback_group_slug is null;
